    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ===== MAIN MESSAGE AREA ===== */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #1a1d21;
    transition: flex 0.2s;
}

.message-area.thread-open {
    /* shrinks to ~55% when thread panel is visible */
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #2c2d30;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #fff;
}

.channel-description {
    font-size: 0.8rem;
    color: #9ea0a5;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.message-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-thumb {
    background: #555;
    border-radius: 3px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #9ea0a5;
    font-size: 0.85rem;
}

