@code {
    private const int PageSize = 30;

    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private int _skip;
    private bool _loadingMore;
    private bool _hasMoreMessages = true;

    private string _newMessageText = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReplyText = "";

    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private ElementReference _messageListRef;

    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _skip = 0;
        _hasMoreMessages = true;
        _messages = new();
        _threadSummaries = new();

        CloseThread();
        _emojiPickerMessageId = null;

        await LoadMessagesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update the channel's unread count locally
        var idx = _channels!.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
            _activeChannel = _channels[idx];
        }
    }

    private async Task LoadMessagesAsync()
    {
        var batch = await ChatService.GetMessagesAsync(_activeChannelId!.Value, _skip, PageSize);
        if (batch.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        // Prepend older messages
        _messages!.InsertRange(0, batch);
        _skip += batch.Count;

        BuildThreadSummaries();
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        if (_messages is null) return;

        var rootIds = _messages.Where(m => m.ReplyToId is null).Select(m => m.Id).ToHashSet();
        var replies = _messages.Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value));

        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task OnMessageListScroll()
    {
        if (_loadingMore || !_hasMoreMessages) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            _loadingMore = true;
            StateHasChanged();

            await LoadMessagesAsync();

            _loadingMore = false;
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var text = _newMessageText.Trim();
        _newMessageText = "";

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, text, null);
        _messages!.Add(msg);
        _skip++;

        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplyText = "";
        _emojiPickerMessageId = null;

        var allThreadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        // Exclude the root message itself from the replies list
        _threadMessages = allThreadMessages.Where(m => m.Id != rootMessage.Id).ToList();
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null) return;

        var text = _threadReplyText.Trim();
        _threadReplyText = "";

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, text, _threadRootMessage.Id);
        _threadMessages!.Add(reply);
        _messages!.Add(reply);
        _skip++;

        BuildThreadSummaries();
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh messages to show updated reactions
        if (_activeChannelId is not null)
        {
            _skip = 0;
            _messages = new();
            _hasMoreMessages = true;
            await LoadMessagesAsync();
        }

        // Refresh thread if open
        if (_threadOpen && _threadRootMessage is not null)
        {
            var all = await ChatService.GetThreadAsync(_threadRootMessage.Id);
            _threadRootMessage = all.FirstOrDefault(m => m.Id == _threadRootMessage.Id) ?? _threadRootMessage;
            _threadMessages = all.Where(m => m.Id != _threadRootMessage.Id).ToList();
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task ScrollToBottom()
    {
        await JS.InvokeVoidAsync("eval", "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list')?.scrollHeight ?? 0)");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 40 ? desc[..37] + "…" : desc;
    }
}

